import{_ as o,o as t,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"단축키 (설정 페이지)","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/settings/hotkeys-page.md","filePath":"ko-KR/user-guide/settings/hotkeys-page.md","lastUpdated":1785993908000}'),a={name:"ko-KR/user-guide/settings/hotkeys-page.md"};function l(n,e,c,d,i,g){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="단축키-설정-페이지" tabindex="-1">단축키 (설정 페이지) <a class="header-anchor" href="#단축키-설정-페이지" aria-label="Permalink to &quot;단축키 (설정 페이지)&quot;">​</a></h1><p>세 개의 탭: <strong>전역</strong>, <strong>플러그인 동작</strong>, <strong>프로세스 차단 목록</strong>입니다. 각 단축키가 실제로 무엇을 하는지는 <a href="./../hotkeys.html">단축키</a> 페이지를 참고하세요 — 이 페이지는 설정 UI 자체를 문서화합니다.</p><h2 id="전역" tabindex="-1">전역 <a class="header-anchor" href="#전역" aria-label="Permalink to &quot;전역&quot;">​</a></h2><p><strong>전역 단축키</strong> 그룹:</p><ul><li><strong>퀵 검색 표시/숨기기</strong> — 레코더 컨트롤. 단일 수정자 키(두 번 누르기 모드, 기본값 <code>Ctrl</code>) 또는 전체 조합을 받아들입니다. 그 옆의 <strong>전체 화면 앱이 포커스를 가진 동안에도 계속 응답</strong> — 체크박스, 기본값 꺼짐 — 은 이 단축키(그리고 빠른 전환, 인라인 검색 활성화)를 아래의 <a href="#process-blacklist">프로세스 차단 목록</a>에서 설명하는 자동 전체 화면 예외 대상에서 제외합니다.</li><li><strong>빠른 전환</strong> — 기본값 <code>Ctrl+G</code>.</li></ul><p><strong>기능 키</strong> 그룹:</p><ul><li>다음 항목(<code>Ctrl+N</code>), 이전 항목(<code>Ctrl+P</code>), 결과로 이동 수정자(기본값 <code>Ctrl</code>, 숫자 1~9와 짝을 이룸), 동작 메뉴 열기(<code>Ctrl+O</code>), 선택 항목으로 완성(<code>Ctrl+Tab</code>), QuickLook(<code>Alt+P</code>), 이전/다음 키워드 기록(<code>Alt+Up</code> / <code>Alt+Down</code>), 키워드 기록 항목 삭제(<code>Ctrl+Delete</code>), 전체 창 열기(기본값 <code>Ctrl+F</code> — 현재 쿼리를 그대로 유지한 채 전체 창을 바로 엽니다. 퀵 창 자체의 로고를 좌클릭하고 메인 창 표시를 선택하는 것과 같은 효과지만, 그 추가 클릭이 없습니다).</li><li>여기의 모든 레코더는 여러분이 누르는 어떤 키나 조합이든(단순한 <code>Tab</code> 같은 키 포함) 받아들이며, 그 바인딩은 그 키가 원래 가지고 있을 수 있는 어떤 하드코딩된 기본 의미보다 우선합니다.</li></ul><p><strong>빠른 탐색</strong> 그룹:</p><ul><li><strong>빈 공간 더블 좌클릭</strong> — 체크박스, 기본값 켜짐.</li><li><strong>빈 공간 미들클릭</strong> — 체크박스, 기본값 켜짐.</li></ul><h2 id="플러그인-동작" tabindex="-1">플러그인 동작 <a class="header-anchor" href="#플러그인-동작" aria-label="Permalink to &quot;플러그인 동작&quot;">​</a></h2><p>플러그인이 등록한 동작(예: 경로 복사, 관리자 권한으로 실행)마다 하나의 항목이 있으며, 플러그인 이름별로 그룹화되어 각각 자체 단축키 레코더를 가집니다. 변경하기 전까지는 플러그인 자체가 제안하는 기본값을 그대로 사용합니다.</p><h2 id="process-blacklist" tabindex="-1">프로세스 차단 목록 <a class="header-anchor" href="#process-blacklist" aria-label="Permalink to &quot;프로세스 차단 목록 {#process-blacklist}&quot;">​</a></h2><p>포그라운드 포커스가 Lertaro의 전역 단축키, 키 입력 가로채기, 빠른 탐색 더블클릭/미들클릭 마우스 트리거를 완전히 억제해야 하는 실행 파일 이름(예: <code>game.exe</code>)을 추가하세요. 대소문자를 구분하지 않으며, <code>.exe</code> 접미사는 선택 사항입니다. <strong>인덱스</strong> 아래의 제외 규칙과 동일한 하나씩 추가/일괄 편집 패턴을 지원합니다: 단일 항목 텍스트 상자와 <strong>프로세스 추가</strong>, 기존 항목 목록, 그리고 <strong>텍스트 생성</strong> / <strong>텍스트 적용</strong>이 있는 일괄 텍스트 상자입니다.</p><p>이는 전체 화면 게임이나 원시 키보드 입력을 가로채는 다른 앱과의 단축키 충돌에 대한 해결책입니다 — 자세한 내용은 <a href="./../troubleshooting.html#전역-단축키가-반응하지-않습니다">문제 해결</a>을 참고하세요. 진짜로 전체 화면인 포그라운드 앱은 어떤 것이든 여기에 항목을 추가하지 않아도 자동으로 동일하게 처리됩니다 — 단, (<strong>전역</strong> 아래, 퀵 검색 표시/숨기기 옆의) <strong>전체 화면 앱이 포커스를 가진 동안에도 계속 응답</strong>이 켜져 있다면 그 예외에서 완전히 제외됩니다. 어느 경우든 활성화된 파일 대화상자는 항상 예외이므로, 그곳에서는 빠른 탐색이 계속 동작합니다.</p>',14)])])}const u=o(a,[["render",l]]);export{h as __pageData,u as default};
